"""Management of files generated by the image-embedding pipeline."""

from pathlib import Path
from typing import List


EMBEDDING_ARTIFACTS = (
    "embeddings.npy",
    "ids.txt",
    "metadata.csv",
    "metadata.jsonl",
    "faiss.index",
    "embedding_manifest.json",
)


def clean_embedding_artifacts(output_dir: Path) -> List[Path]:
    """Remove only generated embedding artifacts; preserve unrelated output files."""
    output_dir = Path(output_dir)
    removed = []
    for filename in EMBEDDING_ARTIFACTS:
        artifact_path = output_dir / filename
        if artifact_path.is_file():
            artifact_path.unlink()
            removed.append(artifact_path)
    return removed
